MW.landmarks=[{x:27,y:10,name:'옛 기록비'},{x:51,y:11,name:'북쪽 봉화'},{x:66,y:19,name:'잊힌 제단'},{x:58,y:42,name:'남쪽 야영지'},{x:29,y:42,name:'이름의 샘'},{x:40,y:27,name:'달의 문'}];
MW.steps=[['talk','남겨진 이야기','안내자에게 이야기를 듣고 원정을 시작하세요.',1],['scout','지워진 길을 따라','기록비, 북쪽 봉화, 남쪽 야영지를 조사하세요.',3],['kill','밤의 흔적','사냥터의 적을 물리쳐 길을 확보하세요.',24],['collect','기억을 줍는 사람','빛나는 기억 조각을 E로 수집하세요.',10],['puzzle','세 빛의 순서','잊힌 제단에서 단서를 읽고 해·달·별의 순서를 맞추세요.',1],['escort','집으로 가는 길','남쪽 야영지의 순례자를 마을로 호위하세요.',1],['defend','지켜야 할 이름','북쪽 봉화에서 몰려오는 적 5차례를 막으세요.',5],['boss','밤의 문지기','동쪽 수호자를 물리치세요. 붉은 공격 범위를 피하세요.',1],['return','조각을 나누다','안내자에게 돌아가 달 조각과 다음 지역의 길을 받으세요.',1]].map(r=>({kind:r[0],title:r[1],detail:r[2],count:r[3]}));
MW.sideTitles=[['약초 향기의 기억','하람의 첫 검','늦은 편지'],['소담의 작은 정원','매듭을 푸는 법','동생의 신발'],['나루의 등불','녹슨 닻','무진의 빈 자리'],['돌무덤의 밥','망가진 방패','전령의 마지막 길'],['눈꽃 차','기록의 무게','봄의 첫 씨앗'],['광부들의 합창','새 손잡이','태오의 장부'],['연꽃의 이름','기억하지 못한 생일','수원의 약속'],['사구의 쉼터','길잡이의 나침반','별 아래의 거래'],['문밖의 가족','젖은 군화','준의 새 열쇠'],['종을 닦는 아이','부서진 염주','침묵 이후'],['시종의 작은 방','벗어둔 갑옷','아린의 초대장'],['새벽에 심는 나무','열두 마을의 선물','누이에게 쓰는 편지']];
MW.items=[{id:'potion',name:'붉은 회복약',type:'use',price:24,desc:'생명력 120 회복'},{id:'ether',name:'푸른 기력약',type:'use',price:30,desc:'기력 80 회복'},{id:'meal',name:'따뜻한 보급식',type:'use',price:65,desc:'8분간 공격력 15% 증가'},{id:'ward',name:'수호 부적',type:'use',price:75,desc:'8분간 받는 피해 20% 감소'}];
for(let tier=1;tier<=4;tier++)for(const [type,names,stat,values,prices]of [['weapon',['월영검','청죽 장검','별철검','여명검'],'atk',[10,24,48,82],[160,440,1050,2200]],['armor',['여행자 도포','청죽 갑옷','별철 호갑','새벽 전투복'],'def',[4,10,20,34],[120,360,850,1800]],['charm',['바람의 매듭','연화 목걸이','별의 인장','열두 달의 표식'],'hp',[45,100,180,300],[180,550,1200,2500]]])MW.items.push({id:type+tier,type,tier,name:names[tier-1],price:prices[tier-1],[stat]:values[tier-1],desc:`${{atk:'공격',def:'방어',hp:'최대 생명'}[stat]} +${values[tier-1]}`});
MW.npcNames=['나래','솔','가온','미루','한결','별하','이든','여울','다온','시우','온유','서린'];
